class ProfileSerializer(serializers.ModelSerializer):
    """Serializer for viewing user profile."""
    workspace = serializers.SerializerMethodField()
    first_name = serializers.SerializerMethodField()
    last_name = serializers.SerializerMethodField()

    class Meta:
        model = User
        fields = ['id', 'name', 'first_name', 'last_name', 'email', 'role', 'is_verified', 'is_active', 'date_of_birth', 'home_address', 'created_at', 'workspace']
        read_only_fields = ['id', 'role', 'is_verified', 'is_active', 'created_at', 'workspace']

    def get_first_name(self, obj):
        if obj.first_name:
            return obj.first_name
        first_name, _ = split_full_name(obj.name)
        return first_name

    def get_last_name(self, obj):
        if obj.last_name:
            return obj.last_name
        _, last_name = split_full_name(obj.name)
        return last_name

    def get_workspace(self, obj):
        """Get workspace info based on user role."""
        workspace_payload = _workspace_context_for_user(user_id=obj.id, role=obj.role)
        workspace_info, _, _ = _normalize_workspace_payload(workspace_payload=workspace_payload, role=obj.role, user_id=obj.id)
        if obj.role in ['analyst', 'executive'] and isinstance(workspace_info, list):
            return workspace_info[0] if workspace_info else None
        return workspace_info

